DROP SCHEMA IF EXISTS fruitful CASCADE;
CREATE SCHEMA fruitful;
SET search_path TO fruitful;
CREATE TABLE portals (id text PRIMARY KEY, country text, city text, currency text, fx_to_zar numeric, status text);
CREATE TABLE menu_lines (sku text PRIMARY KEY, line_en text, price_zar numeric, direct_cost numeric, margin_pct numeric);
CREATE TABLE menu_translations (lang text, sku text, label text);
CREATE TABLE boq_items (dept text, item text, spec text, freq text, agent text, unit_price_zar text, source text, ffp_sku text);
CREATE TABLE malls (rank int, name text, address text, province text, city text, km_from_pta numeric, tier text, contact_email text, wave text);
CREATE TABLE deployment_economics (rank int, mall text, tier text, est_rent_zar numeric, est_profit_zar numeric, capex_zar numeric, payback_months numeric);
CREATE TABLE container_fill (item text, supplier text, unit_cost_usd numeric, cbm numeric, units_loaded int, freight_saved_zar numeric);
CREATE TABLE history_log (ts text, event text, detail text);
CREATE TABLE financial_snapshot (metric text, value_zar numeric, basis text);
CREATE TABLE suppliers (name text, role text, contact text, terms text, status text);
